package tv.plus.pro.switcher;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.provider.Settings;import android.net.Uri;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity{
 LinearLayout body;
 TextView item(String s,Runnable r){TextView v=new TextView(this);v.setText(s);v.setTextSize(17);v.setTextColor(-1);v.setPadding(20,18,20,18);v.setFocusable(true);v.setBackgroundColor(0xff272251);v.setOnClickListener(w->r.run());v.setOnFocusChangeListener((w,f)->v.setBackgroundColor(f?0xff8a3ef0:0xff272251));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,5,0,5);body.addView(v,p);return v;}
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(22,18,22,18);root.setBackgroundColor(0xff0b0e29);TextView title=new TextView(this);title.setText("▶ TV+ Pro  |  Launcher Switcher");title.setTextSize(23);title.setTextColor(-1);root.addView(title);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);item("▶ TV+ Pro'yu Başlat",()->startLauncher());item("⌂ Varsayılan Ana Ekranı Seç",()->chooseHome());item("⚙ Android Ana Ekran Ayarları",()->settings());item("▦ Yüklü Başlatıcıları Listele",()->showLaunchers());item("▣ Uygulama Yönetimi",()->listApps());item("▣ HDMI Giriş Uygulamasını Bul",()->findHdmi());item("ⓘ Güvenli Kullanım Bilgisi",()->new AlertDialog.Builder(this).setMessage("Sistem başlatıcısını ve HDMI bileşenlerini silmeyin. Önce TV+ Pro'nun HOME olarak çalıştığını doğrulayın. HDMI-IN donanımı HDMI-OUT işlevine dönüşmez.").setPositiveButton("Tamam",null).show());}
 void startLauncher(){try{Intent i=getPackageManager().getLaunchIntentForPackage("tv.plus.pro.unified");if(i==null){i=new Intent(Intent.ACTION_MAIN);i.setClassName("tv.plus.pro.unified","tv.plus.pro.home.MainActivity");}startActivity(i);}catch(Exception e){message("TV+ Pro kurulu değil veya başlatılamıyor: "+e.getMessage());}}
 void chooseHome(){try{startActivity(new Intent(Settings.ACTION_HOME_SETTINGS));}catch(Exception e){try{Intent i=new Intent(Intent.ACTION_MAIN);i.addCategory(Intent.CATEGORY_HOME);startActivity(i);}catch(Exception x){message("Bu cihazda ana ekran seçim ekranı bulunamadı.");}}}
 void settings(){try{startActivity(new Intent(Settings.ACTION_SETTINGS));}catch(Exception e){message(e.getMessage());}}
 void showLaunchers(){Intent i=new Intent(Intent.ACTION_MAIN);i.addCategory(Intent.CATEGORY_HOME);showPackages(i,false);}
 void listApps(){Intent i=new Intent(Intent.ACTION_MAIN);i.addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER);showPackages(i,false);}
 void findHdmi(){Intent i=new Intent(Intent.ACTION_MAIN);i.addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER);PackageManager pm=getPackageManager();ArrayList<ResolveInfo> found=new ArrayList<>();for(ResolveInfo r:pm.queryIntentActivities(i,0)){String s=r.loadLabel(pm).toString().toLowerCase(java.util.Locale.ROOT);if(s.contains("hdmi")||s.contains("input")||s.contains("source")||s.contains("kaynak"))found.add(r);}showResults(found,true);}
 void showPackages(Intent i,boolean launch){showResults(getPackageManager().queryIntentActivities(i,0),launch);}
 void showResults(java.util.List<ResolveInfo> results,boolean launch){PackageManager pm=getPackageManager();if(results.isEmpty()){message("Uygulama bulunamadı. Bazı sistem uygulamaları Android tarafından gizlenebilir.");return;}String[] labels=new String[results.size()];for(int n=0;n<results.size();n++)labels[n]=results.get(n).loadLabel(pm)+"\n"+results.get(n).activityInfo.packageName;new AlertDialog.Builder(this).setTitle("Uygulamalar").setItems(labels,(d,n)->{ResolveInfo r=results.get(n);if(launch){try{Intent i=new Intent(Intent.ACTION_MAIN);i.setClassName(r.activityInfo.packageName,r.activityInfo.name);startActivity(i);}catch(Exception e){appInfo(r.activityInfo.packageName);}}else appInfo(r.activityInfo.packageName);}).setNegativeButton("Kapat",null).show();}
 void appInfo(String pkg){try{Intent i=new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+pkg));startActivity(i);}catch(Exception e){message("Uygulama bilgileri açılamadı.");}}
 void message(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("Tamam",null).show();}
}